uniform shader amzt_ds1;
float4 amzSample_ds1(float2 uv) { return float4(amzt_ds1.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_hblur;
float4 amzSample_hblur(float2 uv) { return float4(amzt_hblur.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0)); }
