                    float4 texColor = amzTexture(0,amzScreenNorm());
                    float4 lift = mix(amzTexture(2,amzScreenNorm())*texColor.a,texColor,amzp_fill);
                    amzOutput = (amzp_mode>0.5)? lift : amzTexture(0,amzScreenNorm());
                } else if( amzPass==1 ) {
                    float actualStrength = amzp_strength/10.0;
                    float2 texelSize = 1.0 / getTexSize((screen.zw/2.0));
                    float2 velocity = float2(actualStrength,0.0);
                    float speed = length(velocity / texelSize);
                    int nSamples = int(clamp(speed, 2.01, 150.01));
                    float4 outColor = amzTexture(1,amzScreenNorm().st);
                    for(int i=1; i<nSamples; i++ ) {
                        float2 offset = velocity * (float(i) / float(nSamples - 1));
                        outColor += amzTexture(1, amzScreenNorm().st+offset);
                        outColor += amzTexture(1, amzScreenNorm().st-offset);
                    }
                    float4 result = outColor/float(nSamples*2-1);
                    amzOutput = result;
                } else {
                    float actualStrength = amzp_strength/10.0;
                    float2 texelSize = 1.0 / getTexSize((screen.zw/2.0));
                    float2 velocity = float2(0.0,actualStrength);
                    float speed = length(velocity / texelSize);
                    int nSamples = int(clamp(speed, 2.01, 150.01));
                    float4 outColor = amzTexture(3,amzScreenNorm().st);
                    for(int i=1; i<nSamples; i++ ) {
                        float2 offset = velocity * (float(i) / float(nSamples - 1));
                        outColor += amzTexture(3, amzScreenNorm().st+offset);
                        outColor += amzTexture(3, amzScreenNorm().st-offset);
                    }
                    float4 result = outColor/float(nSamples*2-1);
                    amzOutput = result;
                }
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

